{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2170-08-02 17:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand you've been having nausea, stomach pain, and dry heaves for about a week and a half?"
    },
    {
      "turn_number": 2,
      "time": "2170-08-02 17:16:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. It’s constant pain in my upper belly, and I just can’t keep food down. I feel full after even a few bites."
    },
    {
      "turn_number": 3,
      "time": "2170-08-02 17:17:00",
      "speaker": "Doctor",
      "text": "I see. You mentioned you’re drinking about 2 liters of water a day, but not getting enough calories. Have you noticed any vomiting blood or black stools?"
    },
    {
      "turn_number": 4,
      "time": "2170-08-02 17:18:00",
      "speaker": "Patient",
      "text": "No, no blood or dark stools. No fever either. Just this pain and nausea."
    },
    {
      "turn_number": 5,
      "time": "2170-08-02 17:19:00",
      "speaker": "Doctor",
      "text": "Good, that’s reassuring. Given your history of gastric bypass and previous ulcers, we want to make sure we’re not dealing with another erosion or gastritis."
    },
    {
      "turn_number": 6,
      "time": "2170-08-02 17:20:00",
      "speaker": "Patient",
      "text": "I had something like this before, and it was an erosion. I hope it’s not back."
    },
    {
      "turn_number": 7,
      "time": "2170-08-02 17:21:00",
      "speaker": "Doctor",
      "text": "We’ll check that. For now, we’re starting you on IV fluids to rehydrate you, including a ‘banana bag’ with vitamins, since you’ve been eating so little."
    },
    {
      "turn_number": 8,
      "time": "2170-08-02 17:22:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. I’ve been feeling kind of weak."
    },
    {
      "turn_number": 9,
      "time": "2170-08-02 17:23:00",
      "speaker": "Doctor",
      "text": "We’ve also started IV pantoprazole to reduce stomach acid and help any irritation heal. We’ll get some blood work to check your nutrition and organ function."
    },
    {
      "turn_number": 10,
      "time": "2170-08-03 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs came back. Your blood counts are a bit low, and your albumin is low too, which suggests malnutrition."
    },
    {
      "turn_number": 11,
      "time": "2170-08-03 08:01:00",
      "speaker": "Patient",
      "text": "Oh. So that’s why I feel so tired?"
    },
    {
      "turn_number": 12,
      "time": "2170-08-03 08:02:00",
      "speaker": "Doctor",
      "text": "Partly, yes. We’ve consulted nutrition, and they agree you’re at risk. We’re going to place a PICC line so we can start TPN—total parenteral nutrition—through your vein."
    },
    {
      "turn_number": 13,
      "time": "2170-08-03 08:03:00",
      "speaker": "Patient",
      "text": "TPN? I’ve heard of that. It’s like IV nutrition?"
    },
    {
      "turn_number": 14,
      "time": "2170-08-03 08:04:00",
      "speaker": "Doctor",
      "text": "Exactly. It delivers calories, protein, fats, and vitamins directly into your bloodstream. We’ll start slow to avoid refeeding syndrome, then build up."
    },
    {
      "turn_number": 15,
      "time": "2170-08-03 12:15:00",
      "speaker": "Doctor",
      "text": "The PICC line was placed successfully in your left arm. The chest X-ray confirms it’s in the right spot—near your heart. You should be ready for TPN soon."
    },
    {
      "turn_number": 16,
      "time": "2170-08-03 12:16:00",
      "speaker": "Patient",
      "text": "Great. I hope this helps me feel stronger."
    },
    {
      "turn_number": 17,
      "time": "2170-08-04 07:00:00",
      "speaker": "Doctor",
      "text": "Good news—your labs today show no signs of refeeding syndrome. Your electrolytes are stable, and we’re increasing your TPN dose."
    },
    {
      "turn_number": 18,
      "time": "2170-08-04 07:01:00",
      "speaker": "Patient",
      "text": "That’s good. My nausea is still there, but maybe a little less?"
    },
    {
      "turn_number": 19,
      "time": "2170-08-04 07:02:00",
      "speaker": "Doctor",
      "text": "We’re also giving you ondansetron for nausea. We’ll keep monitoring. One test came back—your H. pylori antibody test was negative, so it’s not that infection causing this."
    },
    {
      "turn_number": 20,
      "time": "2170-08-04 07:03:00",
      "speaker": "Patient",
      "text": "Okay, so not an infection. What else could it be?"
    },
    {
      "turn_number": 21,
      "time": "2170-08-04 07:04:00",
      "speaker": "Doctor",
      "text": "Could be gastritis, a hiatal hernia, or even cyclic vomiting syndrome. We’ll know more after your EGD on day five."
    },
    {
      "turn_number": 22,
      "time": "2170-08-05 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well—still no refeeding issues. TPN is at goal now. We’re starting to cycle it at night, so you’ll have freedom during the day."
    },
    {
      "turn_number": 23,
      "time": "2170-08-05 08:01:00",
      "speaker": "Patient",
      "text": "That sounds nice. I’d like to be able to move around more."
    },
    {
      "turn_number": 24,
      "time": "2170-08-05 08:02:00",
      "speaker": "Doctor",
      "text": "Exactly. And we’re encouraged—your nausea is improving, and pain is less intense. We’ll keep building strength for discharge."
    },
    {
      "turn_number": 25,
      "time": "2170-08-06 07:30:00",
      "speaker": "Doctor",
      "text": "Good morning. Today’s the day for your EGD. It’s an upper endoscopy—we’ll look inside your stomach to see what’s going on."
    },
    {
      "turn_number": 26,
      "time": "2170-08-06 07:31:00",
      "speaker": "Patient",
      "text": "Will I be asleep?"
    },
    {
      "turn_number": 27,
      "time": "2170-08-06 07:32:00",
      "speaker": "Doctor",
      "text": "Yes, you’ll be under sedation. It’s quick, and we’ll have results by this afternoon."
    },
    {
      "turn_number": 28,
      "time": "2170-08-06 14:00:00",
      "speaker": "Doctor",
      "text": "Hi, you’re back. The EGD showed mild gastritis and a small hiatal hernia. No ulcers or bleeding. That’s good news."
    },
    {
      "turn_number": 29,
      "time": "2170-08-06 14:01:00",
      "speaker": "Patient",
      "text": "So no erosion this time?"
    },
    {
      "turn_number": 30,
      "time": "2170-08-06 14:02:00",
      "speaker": "Doctor",
      "text": "No, not this time. But the gastritis and hernia could explain your symptoms. Gastroenterology wants us to increase your pantoprazole to 80 mg twice a day."
    },
    {
      "turn_number": 31,
      "time": "2170-08-06 14:03:00",
      "speaker": "Patient",
      "text": "That’s double what I was on. Is that safe?"
    },
    {
      "turn_number": 32,
      "time": "2170-08-06 14:04:00",
      "speaker": "Doctor",
      "text": "Yes, it’s safe and often used for more severe reflux or hernias. We’ll switch you to IV for now, then you’ll continue at home."
    },
    {
      "turn_number": 33,
      "time": "2170-08-06 14:05:00",
      "speaker": "Patient",
      "text": "Okay. And what about the TPN?"
    },
    {
      "turn_number": 34,
      "time": "2170-08-06 14:06:00",
      "speaker": "Doctor",
      "text": "You’ll keep it for now, but we’re starting you on a stage 5 bariatric diet—small amounts of soft food—to see how you tolerate eating again."
    },
    {
      "turn_number": 35,
      "time": "2170-08-06 14:07:00",
      "speaker": "Patient",
      "text": "I’ll try. I’m nervous I’ll feel full too fast."
    },
    {
      "turn_number": 36,
      "time": "2170-08-06 14:08:00",
      "speaker": "Doctor",
      "text": "That’s normal. Eat slowly, small bites. We’re not expecting you to eat a lot yet. The TPN will cover your needs."
    },
    {
      "turn_number": 37,
      "time": "2170-08-07 07:00:00",
      "speaker": "Doctor",
      "text": "Morning. Great news—you tolerated the diet well overnight, no nausea. Your pain is much better, and you’re walking independently."
    },
    {
      "turn_number": 38,
      "time": "2170-08-07 07:01:00",
      "speaker": "Patient",
      "text": "I feel like I can actually eat again. Not much, but it’s something."
    },
    {
      "turn_number": 39,
      "time": "2170-08-07 07:02:00",
      "speaker": "Doctor",
      "text": "We’re discharging you today. You’ll go home on TPN, cycled at night, and continue IV pantoprazole twice a day."
    },
    {
      "turn_number": 40,
      "time": "2170-08-07 07:03:00",
      "speaker": "Patient",
      "text": "I’ll still need IV meds at home?"
    },
    {
      "turn_number": 41,
      "time": "2170-08-07 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, for now. A nurse will visit to help with the TPN and IV meds. We’ll switch to oral meds when your stomach is ready."
    },
    {
      "turn_number": 42,
      "time": "2170-08-07 07:05:00",
      "speaker": "Patient",
      "text": "And my other meds?"
    },
    {
      "turn_number": 43,
      "time": "2170-08-07 07:06:00",
      "speaker": "Doctor",
      "text": "You’ll resume most—like your citalopram, lamotrigine, and iron. We’ve adjusted doses. Temazepam and lorazepam are now as needed."
    },
    {
      "turn_number": 44,
      "time": "2170-08-07 07:07:00",
      "speaker": "Patient",
      "text": "What about follow-up?"
    },
    {
      "turn_number": 45,
      "time": "2170-08-07 07:08:00",
      "speaker": "Doctor",
      "text": "You’ll see gastroenterology soon to discuss cyclic vomiting syndrome. And Dr. Patel for surgical follow-up. We’ll also need labs: liver tests, electrolytes, albumin, and triglycerides."
    },
    {
      "turn_number": 46,
      "time": "2170-08-07 07:09:00",
      "speaker": "Patient",
      "text": "What if my pain comes back?"
    },
    {
      "turn_number": 47,
      "time": "2170-08-07 07:10:00",
      "speaker": "Doctor",
      "text": "Call us if pain worsens, or if you develop fever, vomiting, black stools, or trouble breathing. Also, watch for signs of dehydration."
    },
    {
      "turn_number": 48,
      "time": "2170-08-07 07:11:00",
      "speaker": "Patient",
      "text": "And the PICC line care?"
    },
    {
      "turn_number": 49,
      "time": "2170-08-07 07:12:00",
      "speaker": "Doctor",
      "text": "A nurse will teach you care before discharge. Keep it clean and dry. Call if you see redness, swelling, or drainage."
    },
    {
      "turn_number": 50,
      "time": "2170-08-07 07:13:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I’m glad I’m on the mend."
    },
    {
      "turn_number": 51,
      "time": "2170-08-07 07:14:00",
      "speaker": "Doctor",
      "text": "You’ve done really well. Keep resting, stay hydrated, and we’ll see you in follow-up. Take care."
    },
    {
      "turn_number": 52,
      "time": "2170-08-07 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick update—your discharge paperwork is ready. You’ll receive 120 vials of IV pantoprazole for twice-daily use at home."
    },
    {
      "turn_number": 53,
      "time": "2170-08-07 10:01:00",
      "speaker": "Patient",
      "text": "Got it. And the multivitamins?"
    },
    {
      "turn_number": 54,
      "time": "2170-08-07 10:02:00",
      "speaker": "Doctor",
      "text": "Hold the multivitamins while on TPN—they’re included in the solution. Resume when TPN stops."
    },
    {
      "turn_number": 55,
      "time": "2170-08-07 10:03:00",
      "speaker": "Patient",
      "text": "Makes sense. And the oxycodone?"
    },
    {
      "turn_number": 56,
      "time": "2170-08-07 10:04:00",
      "speaker": "Doctor",
      "text": "Use only if needed for pain, every 4 hours as needed. Don’t drive while taking it."
    },
    {
      "turn_number": 57,
      "time": "2170-08-07 10:05:00",
      "speaker": "Patient",
      "text": "I won’t. Thanks for explaining everything."
    },
    {
      "turn_number": 58,
      "time": "2170-08-07 10:06:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’re also sending docusate for constipation if needed. And ondansetron for nausea—dissolve one every 8 hours if needed."
    },
    {
      "turn_number": 59,
      "time": "2170-08-07 10:07:00",
      "speaker": "Patient",
      "text": "I haven’t needed it today. That’s a good sign."
    },
    {
      "turn_number": 60,
      "time": "2170-08-07 10:08:00",
      "speaker": "Doctor",
      "text": "It really is. You’ve improved a lot in five days. Keep it up, and call us with any concerns."
    },
    {
      "turn_number": 61,
      "time": "2170-08-07 14:00:00",
      "speaker": "Doctor",
      "text": "Final check before discharge. Your vitals are stable, you’re alert, and you’ve eaten a small meal without issues."
    },
    {
      "turn_number": 62,
      "time": "2170-08-07 14:01:00",
      "speaker": "Patient",
      "text": "I’m ready to go home."
    },
    {
      "turn_number": 63,
      "time": "2170-08-07 14:02:00",
      "speaker": "Doctor",
      "text": "You’re cleared. Remember: follow-up appointments, labs, and call us if anything changes. Take care, and we’ll see you soon."
    },
    {
      "turn_number": 64,
      "time": "2170-08-07 14:03:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I really appreciate all the help."
    },
    {
      "turn_number": 65,
      "time": "2170-08-07 14:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Get some rest, and keep building your strength. You’re on the right path."
    },
    {
      "turn_number": 66,
      "time": "2170-08-07 14:05:00",
      "speaker": "Patient",
      "text": "I will. See you at follow-up."
    },
    {
      "turn_number": 67,
      "time": "2170-08-07 14:06:00",
      "speaker": "Doctor",
      "text": "Take care. The nurse will assist you with discharge now."
    }
  ],
  "summary": {
    "admission_start": "2170-08-02 17:11:00",
    "admission_end": "2170-08-07 15:13:00",
    "summary_paragraph": "The patient was admitted with persistent nausea, epigastric pain, dry heaves, and inability to maintain adequate oral intake for over a week. She has a history of gastric bypass and prior gastric erosion. On admission, she was started on IV fluids, pantoprazole, and anti-nausea medication. Due to malnutrition, a PICC line was placed on hospital day 2, and TPN was initiated and gradually advanced without complications. An EGD on day 5 revealed mild gastritis and a small hiatal hernia, with no ulceration. Pantoprazole was increased to 80 mg twice daily per gastroenterology recommendation. The patient's symptoms improved, she tolerated a stage 5 bariatric diet, and was discharged home on nocturnal TPN and IV pantoprazole with plans for outpatient follow-up in gastroenterology and surgery. Cyclic vomiting syndrome was suggested as a possible contributing diagnosis.",
    "problems": [
      "Unspecified protein-calorie malnutrition",
      "Unspecified gastritis and gastroduodenitis, without mention of hemorrhage",
      "Polycystic ovaries",
      "Bariatric surgery status",
      "Diaphragmatic hernia without mention of obstruction or gangrene"
    ]
  }
}
